function formatBody(message: EmailProviderMessage): string { const sender = message.sender ? `From: ${message.sender}

` : ""; const received = message.receivedAt ? `Received: ${message.receivedAt}

` : ""; return `${sender}${received}${message.body ?? ""}`.trim(); }

